 String french, String question, List<String> options, int answer, String correction) =>
 <String, dynamic>{
  'id':'A2-U03-L${n.toString().padLeft(2,'0')}','level':'A2','title':title,
  'subtitle':'Comparer et décrire • Leçon $n/50','explanation':explanation,
  'example':example,'french':french,'question':question,'options':options,
  'answer':answer,'correction':correction,'unit':3,'phase':0,
 };
final List<Map<String,dynamic>> a2Unit3CourseData = <Map<String,dynamic>>[
 _u3(1,'Comparatif des adjectifs courts','Pour beaucoup d’adjectifs courts, ajoute -er puis than pour comparer deux éléments.','A bike is cheaper than a car.','Un vélo est moins cher qu’une voiture.','Complète : My bag is ___ than yours.',['heavyer','heavier','more heavy'],1,'Heavy devient heavier : y devient i.'),
 _u3(2,'Comparatif avec -e final','Un adjectif qui finit par -e prend généralement seulement -r au comparatif.','This road is wider than that one.','Cette route est plus large que l’autre.','Comparatif correct de wide :',['wider','wideer','more wider'],0,'Wide prend simplement -r.'),
 _u3(3,'Doubler la consonne finale','Pour certains adjectifs courts consonne-voyelle-consonne, double la dernière consonne avant -er.','Today is hotter than yesterday.','Aujourd’hui, il fait plus chaud qu’hier.','Comparatif correct de hot :',['hoter','hotter','more hotter'],1,'Hot devient hotter avec consonne doublée.'),
 _u3(4,'Comparatif des adjectifs longs','Pour beaucoup d’adjectifs longs, utilise more + adjectif + than.','This exercise is more difficult than the last one.','Cet exercice est plus difficile que le précédent.','Complète : This book is ___ interesting than that one.',['interestinger','more','most'],1,'More précède ici l’adjectif long interesting.'),
 _u3(5,'Forme irrégulière better','Good devient better au comparatif ; ne dis pas gooder.','Your idea is better than mine.','Ton idée est meilleure que la mienne.','Comparatif de good :',['gooder','better','best than'],1,'Better est le comparatif irrégulier de good.'),
 _u3(6,'Forme irrégulière worse','Bad devient worse au comparatif.','The weather is worse today.','Le temps est pire aujourd’hui.','Comparatif de bad :',['badder','worse','worst than'],1,'Worse est la forme comparative correcte.'),
 _u3(7,'Comparatif de far','Far peut devenir farther ou further selon le contexte et la variété d’anglais.','The school is farther from here than the shop.','L’école est plus loin d’ici que le magasin.','Quel mot compare une distance ?',['farther','farest','more far'],0,'Farther est courant pour une distance physique.'),
 _u3(8,'Comparer avec less','Less + adjectif signifie moins… que ; than introduit le second élément.','This task is less difficult than the first one.','Cette tâche est moins difficile que la première.','Comment dire « moins cher que » ?',['less expensive than','least expensive than','expensiver than'],0,'Less expensive than exprime une comparaison inférieure.'),
 _u3(9,'Utiliser as…as','As + adjectif + as indique que deux choses sont égales sur un aspect.','My sister is as tall as me.','Ma sœur est aussi grande que moi.','Complète : This room is as big ___ that one.',['than','as','like'],1,'La structure est as big as.'),
 _u3(10,'Négation de as…as','Not as…as signifie pas aussi… que.','This phone isn’t as expensive as that one.','Ce téléphone n’est pas aussi cher que l’autre.','Quel sens a cette phrase ?',['Les deux prix sont forcément égaux.','Ce téléphone coûte moins cher que l’autre.','Ce téléphone est le plus cher.'],1,'Not as expensive as indique un prix inférieur dans ce contexte.'),
 _u3(11,'Superlatif des adjectifs courts','Pour beaucoup d’adjectifs courts, utilise the + adjectif-est.','Mount Kito is the highest hill here.','Le mont Kito est la colline la plus haute ici.','Superlatif de small :',['the smallest','the most small','the smaller'],0,'Small devient the smallest.'),
 _u3(12,'Superlatif avec -e final','Un adjectif qui finit par -e prend généralement -st au superlatif.','It is the largest room in the house.','C’est la plus grande pièce de la maison.','Superlatif de large :',['the larg est','the largest','the most largest'],1,'Large devient the largest.'),
 _u3(13,'Doubler au superlatif','Certains adjectifs courts doublent la consonne avant -est.','That was the hottest day of the year.','C’était le jour le plus chaud de l’année.','Superlatif de hot :',['the hotest','the hottest','the most hot'],1,'Hot devient hottest avec consonne doublée.'),
 _u3(14,'Superlatif des adjectifs longs','Pour beaucoup d’adjectifs longs, utilise the most + adjectif.','This is the most comfortable chair.','C’est le fauteuil le plus confortable.','Superlatif de comfortable :',['the comfortablest','the most comfortable','most comfortable than'],1,'The most comfortable est la forme attendue.'),
 _u3(15,'Superlatif irrégulier best','Good devient the best au superlatif.','She is the best player on our team.','C’est la meilleure joueuse de notre équipe.','Superlatif de good :',['the goodest','the better','the best'],2,'The best est le superlatif irrégulier de good.'),
 _u3(16,'Superlatif irrégulier worst','Bad devient the worst au superlatif.','That was the worst meal I have ever had.','C’était le pire repas que j’aie jamais mangé.','Superlatif de bad :',['the worst','the baddest','the worse'],0,'The worst est le superlatif de bad.'),
 _u3(17,'Choisir between et in avec un superlatif','Utilise souvent in pour un lieu ou un groupe et of pour un ensemble précis.','She is the fastest runner in the class.','C’est la coureuse la plus rapide de la classe.','Complète : the tallest student ___ the class.',['in','at to','of in'],0,'In the class désigne le groupe-classe.'),
 _u3(18,'Utiliser much avec un comparatif','Much ou far devant un comparatif renforce la différence.','This route is much shorter.','Cet itinéraire est beaucoup plus court.','Quel mot renforce le comparatif ?',['much','many of','very than'],0,'Much shorter signifie beaucoup plus court.'),
 _u3(19,'Utiliser a little avec un comparatif','A little + comparatif indique une différence faible.','The blue shirt is a little cheaper.','La chemise bleue est un peu moins chère.','Quel groupe signifie « un peu moins cher » ?',['a little cheaper','the little cheap','little cheapest'],0,'A little cheaper indique une petite différence de prix.'),
 _u3(20,'Adverbes en -ly','Beaucoup d’adverbes se forment en ajoutant -ly à l’adjectif.','She speaks slowly.','Elle parle lentement.','Quel adverbe complète : He drives ___ (careful).',['careful','carefully','carefuller'],1,'Careful devient carefully.'),
 _u3(21,'Adjectif ou adverbe après un verbe','Un adjectif décrit souvent un état après be ; un adverbe décrit la manière d’une action.','The music is loud. They play loudly.','La musique est forte. Ils jouent fort.','Complète : She sings ___.',['beautiful','beautifully','beautifuller'],1,'Sings décrit une action, donc beautifully.'),
 _u3(22,'Adverbes irréguliers well et fast','Good est un adjectif ; well est son adverbe courant. Fast garde souvent la même forme.','He plays well and runs fast.','Il joue bien et court vite.','Adverbe de good :',['goodly','well','betterly'],1,'Well est l’adverbe usuel de good.'),
 _u3(23,'Différencier hard et hardly','Hard signifie avec effort ; hardly signifie presque pas.','She works hard, but she hardly rests.','Elle travaille dur, mais elle se repose à peine.','Hardly signifie :',['avec beaucoup d’effort','presque pas','rapidement'],1,'Hardly signifie presque pas, pas « dur ».'),
 _u3(24,'Adverbes de fréquence','Always, usually, often, sometimes et never indiquent la fréquence.','I usually walk to school.','Je vais généralement à l’école à pied.','Quel adverbe signifie « jamais » ?',['often','never','usually'],1,'Never signifie jamais.'),
 _u3(25,'Position de l’adverbe de fréquence','L’adverbe se place souvent avant le verbe principal, mais après be.','She often reads; she is always kind.','Elle lit souvent ; elle est toujours gentille.','Choisis la phrase naturelle.',['She reads often always.','She often reads.','Often she is reads.'],1,'Often précède le verbe principal reads.'),
 _u3(26,'Too + adjectif','Too signifie excessivement et souvent exprime un problème.','The tea is too hot to drink.','Le thé est trop chaud pour être bu.','Quel est le problème ?',['Le thé est assez froid.','Le thé est excessivement chaud.','Le thé est moins chaud.'],1,'Too hot signifie trop chaud.'),
 _u3(27,'Adjectif + enough','Enough vient après l’adjectif : old enough, strong enough.','He is old enough to travel alone.','Il est assez âgé pour voyager seul.','Complète : The box is light ___ to carry.',['too','enough','many'],1,'Enough se place après light.'),
 _u3(28,'Enough + nom','Avec un nom, enough se place avant le nom : enough time, enough money.','We have enough time to finish.','Nous avons assez de temps pour terminer.','Choisis la structure correcte.',['time enoughs','enough time','enough of time always'],1,'Enough précède le nom time.'),
 _u3(29,'Too much et too many','Too much s’utilise avec les noms indénombrables ; too many avec les noms dénombrables pluriels.','There are too many cars and too much noise.','Il y a trop de voitures et trop de bruit.','Quel groupe convient avec water ?',['too many water','too much water','too much bottles'],1,'Water est indénombrable : too much water.'),
 _u3(30,'Not enough','Not enough indique une quantité insuffisante.','There aren’t enough chairs for everyone.','Il n’y a pas assez de chaises pour tout le monde.','Quel est le sens de not enough chairs ?',['Trop de chaises','Pas assez de chaises','Des chaises très confortables'],1,'Not enough signifie pas assez.'),
 _u3(31,'Comparer des quantités avec more','More + nom indique une quantité plus grande.','We need more water than juice.','Nous avons besoin de plus d’eau que de jus.','Comment dire « plus de livres » ?',['more books','much books','manyer books'],0,'More s’emploie devant le nom books.'),
 _u3(32,'Comparer des quantités avec fewer','Fewer s’utilise avec les noms dénombrables pluriels.','This class has fewer students.','Cette classe a moins d’élèves.','Quel mot convient avec students ?',['less students in formal usage','fewer students','fewest than students'],1,'Fewer s’emploie avec un nom pluriel dénombrable.'),
 _u3(33,'Less avec un indénombrable','Less s’utilise généralement avec une quantité indénombrable.','I drink less coffee now.','Je bois moins de café maintenant.','Choisis la bonne expression.',['less coffee','fewer coffee','few coffee than'],0,'Coffee est indénombrable dans ce sens.'),
 _u3(34,'Comparer avec like et unlike','Like indique une ressemblance ; unlike souligne une différence.','Unlike his brother, Tom enjoys cooking.','Contrairement à son frère, Tom aime cuisiner.','Unlike introduit :',['une différence','une égalité exacte','une heure'],0,'Unlike signifie contrairement à.'),
 _u3(35,'Employer both','Both signifie les deux et s’emploie avec un pluriel.','Both answers are correct.','Les deux réponses sont correctes.','Complète : Both students ___ ready.',['is','are','be'],1,'Both students est pluriel, donc are.'),
 _u3(36,'Employer either','Either peut signifier l’un ou l’autre parmi deux choix.','You can take either road.','Tu peux prendre l’une ou l’autre route.','Either road signifie :',['les deux routes ensemble','l’une ou l’autre des deux routes','aucune route'],1,'Either présente une possibilité parmi deux.'),
 _u3(37,'Employer neither','Neither signifie aucun des deux et s’emploie souvent avec un verbe singulier en anglais standard.','Neither answer is correct.','Aucune des deux réponses n’est correcte.','Complète : Neither option ___ cheap.',['are','is','be'],1,'Neither option est singulier, donc is.'),
 _u3(38,'Comparer deux expériences','Utilise comparatifs et adjectifs de sentiment pour comparer des expériences.','The second film was more exciting than the first.','Le deuxième film était plus passionnant que le premier.','Quel film était plus passionnant ?',['The first','The second','Both were yesterday'],1,'More exciting than indique que le second film l’était davantage.'),
 _u3(39,'Décrire une ville avec précision','Combine des adjectifs et des comparatifs pour décrire taille, bruit et coût.','The city centre is busier and noisier at night.','Le centre-ville est plus animé et bruyant la nuit.','Quel mot signifie « plus bruyant » ?',['noisier','noisiest','more noise'],0,'Noisy devient noisier au comparatif.'),
 _u3(40,'Comparer des moyens de transport','Utilise les comparatifs pour parler du coût, de la vitesse et du confort.','The train is usually faster than the bus.','Le train est généralement plus rapide que le bus.','Quel mot compare la vitesse ?',['faster','fastest','fastly'],0,'Faster est le comparatif de fast.'),
 _u3(41,'Décrire une personne','Combine be + adjectif et un adverbe pour décrire caractère et comportement.','Mina is patient and explains things clearly.','Mina est patiente et explique les choses clairement.','Quel mot décrit la manière d’expliquer ?',['patient','clearly','things'],1,'Clearly est un adverbe qui décrit explains.'),
 _u3(42,'Éviter le double comparatif','N’ajoute pas more devant un adjectif déjà marqué par -er.','Correct: simpler, not more simpler.','Correct : plus simple, pas « more simpler ».','Quelle forme est correcte ?',['more easier','easier','most easier than'],1,'Easier suffit ; n’ajoute pas more.'),
 _u3(43,'Éviter le double superlatif','Ne combine pas most avec -est pour le même adjectif.','Correct: the funniest, not the most funniest.','Correct : le plus drôle, pas « the most funniest ».','Quelle forme est correcte ?',['the most funniest','the funniest','the funnierest'],1,'Funniest est déjà un superlatif.'),
 _u3(44,'Utiliser than après un comparatif','Than introduit l’élément auquel on compare.','My new shoes are more comfortable than my old ones.','Mes nouvelles chaussures sont plus confortables que les anciennes.','Quel mot introduit la comparaison ?',['then','than','that'],1,'Than signifie ici que dans une comparaison.'),
 _u3(45,'Employer the same as','The same as signifie identique à ou le même que.','Our uniforms are the same as theirs.','Nos uniformes sont les mêmes que les leurs.','Quel groupe signifie « le même que » ?',['the same as','same than','as same than'],0,'La structure correcte est the same as.'),
 _u3(46,'Employer different from','Different from est une structure courante pour exprimer une différence.','This answer is different from yours.','Cette réponse est différente de la tienne.','Quelle préposition suit different dans cette phrase ?',['than','from','as'],1,'Different from est la structure utilisée ici.'),
 _u3(47,'Nuancer une comparaison','A bit, a little, much et far peuvent modifier un comparatif.','This exercise is a bit easier than the previous one.','Cet exercice est un peu plus facile que le précédent.','Quel groupe signifie « un peu plus facile » ?',['a bit easier','a bit easiest','more easier'],0,'A bit précède le comparatif easier.'),
 _u3(48,'Comprendre une annonce comparative','Repère les adjectifs comparatifs et le critère utilisé dans une publicité ou une annonce.','Our new plan is cheaper and more flexible.','Notre nouvelle offre est moins chère et plus flexible.','Quels deux avantages sont annoncés ?',['cheaper and more flexible','the cheapest yesterday','cheaply and flexibility'],0,'L’annonce compare le prix et la flexibilité.'),
 _u3(49,'Réviser comparatifs et superlatifs','Identifie si la phrase compare deux éléments ou classe un élément au sommet d’un groupe.','This is the most useful app I have tried.','C’est l’application la plus utile que j’aie essayée.','La phrase exprime :',['une comparaison entre exactement deux options','un superlatif','une action passée seulement'],1,'The most useful classe l’application au sommet du groupe.'),
 _u3(50,'Bilan : décrire et comparer','Révise les formes comparatives, superlatives, les adverbes et les quantités.','The library is quieter than the café and it has the most comfortable chairs.','La bibliothèque est plus calme que le café et possède les fauteuils les plus confortables.','Quelle phrase utilise correctement un comparatif et un superlatif ?',['The library is quieter than the café and has the most comfortable chairs.','The library is more quieter and most comfortable chairs.','The library quieter than café and comfortablest.'],0,'Quieter compare deux lieux ; the most comfortable est un superlatif.'),
];
